(E'sha256:5d69f010d2d6756f31b4312d6c1ba40e7fc454417d5acd275053c69ab97527e4',E'["{\\"catalogActive\\":false,\\"dimensions\\":[{\\"allowedValues\\":",725,",\\"mode\\":\\"descriptive\\",\\"signature\\":",1180,",\\"source\\":null,\\"variants\\":[{\\"template\\":{\\"actions\\":",1184,",\\"answerBands\\":[],\\"bands\\":[],\\"basis\\":\\"descriptive\\",\\"code\\":\\"continuous\\",\\"construct\\":\\"Перегрузка от экранов и облегчение\\",\\"continuous\\":true,\\"currentAnswerBand\\":null,\\"currentBand\\":null,\\"label\\":\\"Описательный результат (0–4)\\",\\"limitations\\":",1185,",\\"meaning\\":\\"Перегрузка от экранов и облегчение: {{value}} (0–4). Это среднее ответов о трудностях и способах совладания; оно не позволяет отделить нагрузку от поддержки. Среднее 6 ответов. Проверенные клинические категории для этого результата здесь не присваиваются. Это авторский опросник Holistic House для самонаблюдения. Его результат нельзя считать валидированной клинической оценкой или доказательством эффективности помощи. Вопросы были на английском. Русский текст пояснения не является валидированной русской адаптацией опросника. В этой неизменённой версии среднее объединяет утверждения о трудности и о совладании без разворота ответов. Его нельзя читать как чистую тяжесть проблемы; рассматривайте оба вида опыта отдельно.\\",\\"presentationDirection\\":\\"neutral\\",\\"recommendedReview\\":false,\\"reliableDirection\\":false,\\"source\\":null,\\"summary\\":",1186,",\\"verified\\":true},\\"values\\":",725,"}]}],\\"discoveryClassification\\":",15,",\\"interpretationVersion\\":\\"2026-10-17.v1\\",\\"provenance\\":",1182,",\\"rendererStrategy\\":\\"finite-domain-template.v1\\",\\"reportLocale\\":\\"ru\\",\\"rulesEngineVersion\\":\\"2026-10-16.v10\\",\\"schemaVersion\\":\\"hh-interpretation.v1\\",\\"source\\":",1183,",\\"sourceCommit\\":\\"584371be44e4eedc4c980a0bc483f0676402e2e9\\",\\"sourceHashes\\":",18,",\\"templateCompiler\\":\\"acorn-8.16.0-numeric-template-v1\\",\\"timeframe\\":\\"righ