(E'sha256:6306b394330c9134003270f36238db74ff9db626ac4f4a46f28aa89c8cd66f0b',E'["{\\"catalogActive\\":true,\\"dimensions\\":[{\\"allowedValues\\":",4688,",\\"mode\\":\\"descriptive\\",\\"signature\\":",4689,",\\"source\\":",4690,",\\"variants\\":[{\\"template\\":{\\"actions\\":[\\"Use {{value}} (0–100) on financial well-being (cfpb calibrated) as a starting observation: describe a concrete situation and its impact on the day. Compare only the same version, questionnaire language and reference period.\\",\\"Consider what contributes to financial security and choice. Interpret the U.S.-calibrated score as one self-report measure, not a prescription or income grade.\\"],\\"answerBands\\":[],\\"bands\\":[],\\"basis\\":\\"descriptive\\",\\"code\\":\\"continuous\\",\\"construct\\":\\"Financial well-being (CFPB calibrated)\\",\\"continuous\\":true,\\"currentAnswerBand\\":null,\\"currentBand\\":null,\\"label\\":\\"Descriptive score (0–100)\\",\\"limitations\\":",128,",\\"meaning\\":\\"Financial well-being (CFPB calibrated): {{value}} (0–100). The score uses the official age-and-administration lookup calibrated in the United States. Higher scores reflect greater reported financial security and freedom of choice; they do not measure income, assets or creditworthiness. No verified clinical categories are assigned to this result here.\\",\\"presentationDirection\\":\\"resource\\",\\"recommendedReview\\":false,\\"reliableDirection\\":true,\\"source\\":",4690,",\\"summary\\":\\"The score uses the official age-and-administration lookup calibrated in the United States. Higher scores reflect greater reported financial security and freedom of choice; they do not measure income, assets or creditworthiness.\\",\\"verified\\":true},\\"values\\":",4688,"}]}],\\"discoveryClassification\\":",129,",\\"interpretationVersion\\":\\"2026-10-17.v1\\",\\"provenance\\":",4691,",\\"rendererStrategy\\":\\"finite-domain-template.v1\\",\\"reportLocale\\":\\"en\\",\\"rulesEngineVersion\\":\\"2026-10-16.